type agreementNativeHTMLDelimiterOwner struct {
	Site, Root, Node, Line int
	Closure                bool
	Span                   graph.Span
}

// A complete delimiter run must belong to one declared raw HTML segment.
func agreementNativeHTMLDelimiterOwnerReading(body string, sites []agreementNativeHTMLAddressSite, span graph.Span) (agreementNativeHTMLDelimiterOwner, bool) {
	var owner agreementNativeHTMLDelimiterOwner
	if span.Start < 0 || span.Stop > len(body) || span.Stop <= span.Start || body[span.Start:span.Stop] != strings.Repeat("`", span.Stop-span.Start) || (span.Start > 0 && body[span.Start-1] == 96) || (span.Stop < len(body) && body[span.Stop] == 96) {
		return owner, false
	}
	found := false
	for i := range sites {
		site := &sites[i]
		if site.Kind != ast.KindHTMLBlock.String() || !site.Raw {
			continue
		}
		for li, line := range site.Lines {
			if span.Start >= line.Start && span.Stop <= line.Stop {
				if found {
					return owner, false
				}
				found = true
				owner = agreementNativeHTMLDelimiterOwner{Site: i, Root: site.Root, Node: site.Node, Line: li, Span: span}
			}
		}
		if site.HasClosure && span.Start >= site.Closure.Start && span.Stop <= site.Closure.Stop {
			if found {
				return owner, false
			}
			found = true
			owner = agreementNativeHTMLDelimiterOwner{Site: i, Root: site.Root, Node: site.Node, Line: -1, Closure: true, Span: span}
		}
	}
	return owner, found
}

func agreementNativeHTMLDelimiterPrivate(body string, sites []agreementNativeHTMLAddressSite, span graph.Span) (string, agreementNativeHTMLDelimiterOwner, bool) {
	owner, ok := agreementNativeHTMLDelimiterOwnerReading(body, sites, span)
	if !ok {
		return "", owner, false
	}
	return body[:span.Start] + strings.Repeat("t", span.Stop-span.Start) + body[span.Stop:], owner, true
}

func agreementNativeHTMLDelimiterCurrent(failures []agreementFailure) map[string]int {
	signatures := make(map[string]int)
	for i := range failures {
		signatures[agreementSignature(&failures[i])]++
	}
	return signatures
}

