func agreementNativeHTMLDelimiterDifference(c agreementCase, f *agreementFailure, raw string, page *agreementHTML, failures []agreementFailure) (kind, authority, wrong string) {
	if f == nil || page == nil || c.Title != "" || len(c.Companions) != 0 || f.Property != "P2" || f.Identity != "wikilink-in-code" || f.Direction != "page-in-code" || f.Multiplicity < 1 || f.Fragment != "" || f.Cut != "" || f.PagePresent || f.JudgeAccepted || f.ExcerptFound {
		return "", "", ""
	}
	witnesses := agreementNativeHTMLDelimiterWitnesses()
	for wi := range witnesses {
		w := &witnesses[wi]
		if c.Body != w.Body {
			continue
		}
		if w.Selected[agreementSignature(f)] != 1 {
			return "", "", ""
		}
		native := agreementNativeOwnerReading(c.Body)
		check := agreementNativeCheckReading(c.Body, native)
		html := agreementNativeHTMLAddressSites(c.Body)
		tree := agreementNativeProseAddressTreeReading(c.Body, nil)
		parts, pok := agreementCodeWindowParts(raw)
		private, owner, ok := agreementNativeHTMLDelimiterPrivate(c.Body, html, w.Owner.Span)
		if !ok || !pok || !tree.Valid || len(native.Code) != 0 || private != w.Private || owner != w.Owner || !cmp.Equal(native, w.Native) || !cmp.Equal(check, w.Check) || !cmp.Equal(html, w.HTML) || !cmp.Equal(tree, w.Tree) || !cmp.Equal(judge.LinkTargets(c.Body), w.Targets) || !cmp.Equal(parts, w.Parts) || !cmp.Equal(*page, w.Page) || !maps.Equal(agreementNativeHTMLDelimiterCurrent(failures), w.Signatures) {
			return "", "", ""
		}
		return "debt", "#1011 stage 5", "page"
	}
	return "", "", ""
}

func TestAgreementNativeHTMLDelimiterSource(t *testing.T) {
	t.Parallel()
	witnesses := agreementNativeHTMLDelimiterWitnesses()
	for wi := range witnesses {
		w := &witnesses[wi]
		t.Run(w.Name, func(t *testing.T) {
			t.Parallel()
			for _, body := range []string{w.Body, w.Private} {
				native := agreementNativeOwnerReading(body)
				if diff := cmp.Diff(w.Native, native); diff != "" {
					t.Fatalf("caught: complete native HTML delimiter facts (-want +got):\n%s", diff)
				}
				if diff := cmp.Diff(w.Check, agreementNativeCheckReading(body, native)); diff != "" {
					t.Fatalf("caught: complete HTML delimiter physical fields (-want +got):\n%s", diff)
				}
				if diff := cmp.Diff(w.HTML, agreementNativeHTMLAddressSites(body)); diff != "" {
					t.Fatalf("caught: complete raw HTML delimiter declarations (-want +got):\n%s", diff)
				}
				if diff := cmp.Diff(w.Tree, agreementNativeProseAddressTreeReading(body, nil)); diff != "" {
					t.Fatalf("caught: complete HTML delimiter trees (-want +got):\n%s", diff)
				}
				if diff := cmp.Diff(w.Targets, judge.LinkTargets(body)); diff != "" {
					t.Fatalf("caught: complete unchanged HTML delimiter check targets (-want +got):\n%s", diff)
				}
			}
			private, owner, ok := agreementNativeHTMLDelimiterPrivate(w.Body, w.HTML, w.Owner.Span)
			if !ok || private != w.Private || owner != w.Owner {
				t.Fatal("caught: exact raw HTML delimiter ownership and only its bytes")
			}
		})
	}
}

